 function start(){score=0;wave=1;kills=0;spawnTimer=.5;shots=[];enemies=[];orbs=[];particles=[];player={x:W/2,y:H/2,r:13,hp:3,speed:245,energy:1,dash:0,dashTime:0,invuln:1,fire:0,aim:-Math.PI/2};state='playing';overlay.classList.add('hidden');showToast('WAVE 01');updateHud();sound(600,.13,'triangle')}
 function showToast(t){toast.textContent=t;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),1250)}
 function pause(){if(state==='playing'){state='paused';showOverlay('paused')}else if(state==='paused'){state='playing';overlay.classList.add('hidden');last=performance.now()}}
 function showOverlay(mode){overlay.classList.remove('hidden');if(mode==='paused'){$('eyebrow').textContent='Take a breath';$('title').innerHTML='PAUSED';$('message').textContent='The stars can wait. Your mission is right where you left it.';$('startBtn').textContent='Resume mission';$('startBtn').onclick=pause}else if(mode==='over'){$('eyebrow').textContent='Signal lost';$('title').innerHTML='GAME<br><span>OVER</span>';$('message').innerHTML=`You held the line through wave ${wave}. Final score: <strong style="color:#ffe179">${score}</strong>`;$('startBtn').textContent='Try again';$('startBtn').onclick=start}else{$('eyebrow').textContent='A signal in the dark';$('title').innerHTML='COSMIC<br><span>KEEPER</span>';$('message').textContent='The rift is waking up. Hold the line, collect star cores, and keep your little corner of the cosmos alive.';$('startBtn').textContent='Launch mission';$('startBtn').onclick=start}}
-$('startBtn').onclick=start;$('pauseBtn').onclick=pause;$('soundBtn').onclick=()=>{$.soundOn=!soundOn};
-// Correct property assignment for sound toggle.
+$('startBtn').onclick=start;$('pauseBtn').onclick=pause;
 $('soundBtn').onclick=()=>{soundOn=!soundOn;$('soundBtn').style.color=soundOn?'#68f0de':'#77809a';$('soundBtn').textContent=soundOn?'♫':'♩'};
 window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k==='escape'||k==='p')pause();if(k===' '&&state==='playing')dash()});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
 canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)/r.width*W;pointer.y=(e.clientY-r.top)/r.height*H;pointer.active=true});
 function dash(){if(state!=='playing'||player.energy<.35||player.dashTime>0)return;let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joy.x,dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joy.y;let m=Math.hypot(dx,dy);if(m<.1){dx=Math.cos(player.aim);dy=Math.sin(player.aim)}else{dx/=m;dy/=m}player.dash= .19;player.dashTime=.85;player.energy-=.35;player.invuln=.32;player._dx=dx;player._dy=dy;burst(player.x,player.y,'#68f0de',14,160);sound(180,.18,'sawtooth',.045)}
